'use server';

import { revalidateTag } from 'next/cache';

export async function CacheInvalidationForm() {
  async function invalidateProductsCache() {
    'use server';

    revalidateTag('products');

    return { success: true, timestamp: new Date().toISOString() };
  }

  return (
    <form action={invalidateProductsCache} className="cache-form">
      <h3>Cache Management</h3>
      <p className="cache-info">
        This form demonstrates selective cache invalidation. When submitted, 
        it will invalidate the "products" cache tag, forcing the ProductListing 
        component to refetch fresh data on the next request.
      </p>
      <button type="submit" className="invalidate-btn">
        Invalidate Products Cache
      </button>
      <p className="cache-note">
        Note: The cache will be invalidated immediately, but you may need to 
        refresh the page to see updated data if the database has changed.
      </p>
    </form>
  );
}

